(() => {
  const T = window.__three
  const st = window.__store.getState()
  const H = st.floorPlan.ceilingHeight
  const V3 = T.camera.position.constructor
  const rc = T.raycaster
  const down = new V3(0, -1, 0)
  // The B2/B3 partition (`wall-int-b2-b3`, x=6.19, z=0.1..3.775, 100 mm) ends in a
  // T-junction on `wall-int-bedroom-S` (z=3.775, 100 mm). Sample the wall-top band
  // around that junction and cast DOWN: a sample that does not land on a wall top has
  // fallen through a gap to the floor/furniture/background below.
  const HALF = 0.05 + 0.012 // half thickness + crown proud
  const inBand = (x, z) =>
    (Math.abs(x - 6.19) <= HALF && z >= 0.1 && z <= 3.775) ||
    (Math.abs(z - 3.775) <= HALF && x >= 3.33 && x <= 9.175)
  const STEP = 0.002
  let band = 0, gap = 0, top = 0
  const gapHits = {}
  for (let x = 6.0; x <= 6.38; x += STEP) {
    for (let z = 3.60; z <= 3.95; z += STEP) {
      if (!inBand(x, z)) continue
      band++
      rc.set(new V3(x, H + 2, z), down)
      const hits = rc.intersectObjects(T.scene.children, true)
      let hit = null
      for (const h of hits) {
        const o = h.object
        if (!o.visible) continue
        let p = o.parent, vis = true
        while (p) { if (!p.visible) { vis = false; break } p = p.parent }
        if (!vis) continue
        const m = o.material
        if (m && m.colorWrite === false) continue
        hit = h
        break
      }
      if (hit && hit.point.y >= H - 0.02) { top++; continue }
      gap++
      const key = hit ? (hit.object.name || hit.object.type) + '@' + hit.point.y.toFixed(2) : 'none'
      gapHits[key] = (gapHits[key] || 0) + 1
    }
  }
  console.log('[probe] wall-top-gap ' + JSON.stringify({
    orbitCleanCut: st.featureFlags.orbitCleanCut,
    chromaticAberration: st.featureFlags.chromaticAberration,
    samplesInBand: band, onWallTop: top, gaps: gap,
    gapFraction: +(gap / Math.max(1, band)).toFixed(4),
    worst: Object.entries(gapHits).sort((a, b) => b[1] - a[1]).slice(0, 6),
  }))
})()
